new='''from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            colors = {grid[y][x] for y, x in cells}
            graph = {color: set() for color in colors}
            outer = set()
            for y, x in cells:
                color = grid[y][x]
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if not (0 <= ny < h and 0 <= nx < w) or grid[ny][nx] == 0:
                        outer.add(color)
                    elif grid[ny][nx] != color:
                        graph[color].add(grid[ny][nx])
            root = min(outer) if outer else next(iter(colors))
            layers = []
            visited = {root}
            q2 = deque([root])
            while q2:
                color = q2.popleft()
                layers.append(color)
                for neighbor in graph[color]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        q2.append(neighbor)
            layers.extend(color for color in colors if color not in visited)
            mapping = dict(zip(layers, reversed(layers)))
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out
'''
